17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.assignment.CustomerCodeGenerator;
39	import org.springframework.samples.petclinic.rest.assignment.HouseholdRegistrar;
40	import org.springframework.samples.petclinic.rest.error.DuplicateTelephoneException;
41	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
42	import org.springframework.samples.petclinic.rest.validation.CityOwnerLimitValidator;
43	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
45	import org.springframework.samples.petclinic.rest.validation.OwnerRequestValidator;
46	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    private final OwnerRequestValidator ownerRequestValidator;
74	
75	    private final HouseholdDuplicateValidator householdDuplicateValidator;
76	
77	    private final CityOwnerLimitValidator cityOwnerLimitValidator;
78	
79	    private final TelephoneNormalizer telephoneNormalizer;
80	
81	    private final EmailNormalizer emailNormalizer;
82	
83	    private final AddressNormalizer addressNormalizer;
84	
85	    private final CustomerCodeGenerator customerCodeGenerator;
86	
87	    private final HouseholdRegistrar householdRegistrar;
88	
89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper,
93	                                 OwnerRequestValidator ownerRequestValidator,
94	                                 HouseholdDuplicateValidator householdDuplicateValidator,
95	                                 CityOwnerLimitValidator cityOwnerLimitValidator,
96	                                 TelephoneNormalizer telephoneNormalizer,
97	                                 EmailNormalizer emailNormalizer,
98	                                 AddressNormalizer addressNormalizer,
99	                                 CustomerCodeGenerator customerCodeGenerator,
100	                                 HouseholdRegistrar householdRegistrar) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	        this.ownerRequestValidator = ownerRequestValidator;
106	        this.householdDuplicateValidator = householdDuplicateValidator;
107	        this.cityOwnerLimitValidator = cityOwnerLimitValidator;
108	        this.telephoneNormalizer = telephoneNormalizer;
109	        this.emailNormalizer = emailNormalizer;
110	        this.addressNormalizer = addressNormalizer;
111	        this.customerCodeGenerator = customerCodeGenerator;
112	        this.householdRegistrar = householdRegistrar;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
144	        this.ownerRequestValidator.validate(ownerFieldsDto);
145	        this.householdDuplicateValidator.validate(ownerFieldsDto);
146	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
147	        String telephone = this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
148	        ownerFieldsDto.setTelephone(telephone);
149	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
150	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
151	            throw new DuplicateTelephoneException(telephone);
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        owner.setCustomerCode(
156	            this.customerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
157	                this.clinicService.countOwnersInCity(owner.getCity())));
158	        owner.setNamesakeCount(
159	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
160	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
161	            this.householdRegistrar.register(owner);
162	        }
163	        this.clinicService.saveOwner(owner);
164	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
173	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
174	        if (currentOwner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        currentOwner.setAddress(ownerFieldsDto.getAddress());
178	        currentOwner.setCity(ownerFieldsDto.getCity());
179	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
180	        currentOwner.setLastName(ownerFieldsDto.getLastName());
181	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
182	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
183	        this.clinicService.saveOwner(currentOwner);
184	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Transactional
189	    @Override
190	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        this.clinicService.deleteOwner(owner);
196	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
202	        Owner owner = this.clinicService.findOwnerById(ownerId);
203	        if (owner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        HttpHeaders headers = new HttpHeaders();
207	        Pet pet = petMapper.toPet(petFieldsDto);
208	        owner.setId(ownerId);
209	        pet.setOwner(owner);
210	        pet.getType().setName(null);
211	        this.clinicService.savePet(pet);
212	        PetDto petDto = petMapper.toPetDto(pet);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
214	            .buildAndExpand(pet.getId()).toUri());
215	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
221	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
222	        if (currentOwner != null) {
223	            Pet currentPet = this.clinicService.findPetById(petId);
224	            if (currentPet != null) {
225	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
226	                currentPet.setName(petFieldsDto.getName());
227	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
228	                this.clinicService.savePet(currentPet);
229	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
236	    @Override
237	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
238	        HttpHeaders headers = new HttpHeaders();
239	        Visit visit = visitMapper.toVisit(visitFieldsDto);
240	        Pet pet = new Pet();
241	        pet.setId(petId);
242	        visit.setPet(pet);
243	        this.clinicService.saveVisit(visit);
244	        VisitDto visitDto = visitMapper.toVisitDto(visit);
245	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
246	            .buildAndExpand(visit.getId()).toUri());
247	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
